class Solution {
  asteroidCollision(asteroids) {
    const n = asteroids.length;
    const stack = [];
    let i = n - 1;
    while (i >= 0) {
      if (stack.length === 0) {
        stack.push(asteroids[i]);
        i--;
        continue;
      }
      const top = stack[stack.length - 1];

      // collision case
      if (top < 0 && asteroids[i] > 0) {
        const result = top + asteroids[i];
        // opp ast is bigger, so decrement i
        if (result < 0) {
          i--;
        } else if (result > 0) {
          // forward ast is bigger, so pop opp ast from stack, and do not decrement i
          stack.pop();
        } else {
          // both are same magnitude, so pop opp ast from stack, and decrement i
          stack.pop();
          i--;
        }
      } else {
        stack.push(asteroids[i]);
        i--;
      }
    }
    return stack.reverse();
  }
}

```

