class Solution {
    public int[] asteroidCollision(int[] asteroids) {
        // ArrayDeque is the recommended Stack implementation in Java
        Deque<Integer> stack = new ArrayDeque<>();

        for (int a : asteroids) {
            if (a > 0) {
                stack.addLast(a);
            } else {
                // Collision occurs only if current is negative and top is positive
                while (!stack.isEmpty() && stack.peekLast() > 0 && stack.peekLast() < -a) {
                    stack.pollLast();
                }

                if (stack.isEmpty() || stack.peekLast() < 0) {
                    stack.addLast(a);
                } else if (stack.peekLast() == -a) {
                    stack.pollLast(); // Both explode
                }
                // If stack.peekLast() > -a, the current asteroid 'a' is destroyed (do nothing)
            }
        }

        // Efficiently convert to primitive int array
        return stack.stream().mapToInt(Integer::intValue).toArray();
    }
}
